<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
require __DIR__ . '/app/layout.php';

$action = $_GET['action'] ?? '';
if ($action === 'logout') { session_destroy(); header('Location: index.php?page=login'); exit; }

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $intent = $_POST['intent'] ?? '';
    if ($intent === 'login') {
        $st = db()->prepare('SELECT id, password_hash FROM users WHERE email = :email');
        $st->execute(['email' => strtolower(trim($_POST['email'] ?? ''))]); $account = $st->fetch();
        if ($account && password_verify($_POST['password'] ?? '', $account['password_hash'])) { session_regenerate_id(true); $_SESSION['user_id'] = $account['id']; redirect('dashboard'); }
        flash('danger', 'E-mail ou senha inválidos.'); redirect('login');
    }
    $user = require_login(); $id = (int) $user['id'];
    if ($intent === 'settings') {
        db()->prepare('UPDATE user_settings SET content_enabled=:c, dating_enabled=:d, integration_enabled=:i, visitor_identity_consent=:v WHERE user_id=:id')->execute(['c'=>isset($_POST['content_enabled']),'d'=>isset($_POST['dating_enabled']),'i'=>isset($_POST['integration_enabled']),'v'=>isset($_POST['visitor_identity_consent']),'id'=>$id]);
        flash('success', 'Preferências atualizadas. A integração exige o consentimento explícito de ambas as partes.'); redirect('settings');
    }
    if ($intent === 'publish') {
        db()->prepare('INSERT INTO content_posts (producer_id,title,description,access_type,is_adult,visibility,status) VALUES (:id,:title,:description,:access,:adult,:visibility,\'published\')')->execute(['id'=>$id,'title'=>trim($_POST['title']),'description'=>trim($_POST['description']),'access'=>$_POST['access_type'],'adult'=>isset($_POST['is_adult']),'visibility'=>$_POST['visibility']]);
        flash('success', 'Publicação criada.'); redirect('content');
    }
    if ($intent === 'like') {
        $target=(int)$_POST['target_id'];
        if (eligible_for_interaction($id,$target)) { db()->prepare("INSERT INTO relationship_interests (from_user_id,to_user_id,origin,status) VALUES (:from,:to,:origin,'pending') ON CONFLICT (from_user_id,to_user_id) DO UPDATE SET status='pending', created_at=NOW()") ->execute(['from'=>$id,'to'=>$target,'origin'=>$_POST['origin']]); flash('success','Interesse registrado. Um match só acontece mediante reciprocidade.'); }
        else flash('warning','Esta interação não está elegível no momento.');
        redirect($_POST['return_page'] ?? 'discover');
    }
    if ($intent === 'respond') {
        $interest=(int)$_POST['interest_id']; $decision=$_POST['decision'];
        $st=db()->prepare('SELECT * FROM relationship_interests WHERE id=:id AND to_user_id=:user AND status=\'pending\''); $st->execute(['id'=>$interest,'user'=>$id]); $item=$st->fetch();
        if ($item && $decision === 'like' && eligible_for_interaction($id,(int)$item['from_user_id'])) { db()->prepare("UPDATE relationship_interests SET status='accepted', responded_at=NOW() WHERE id=:id")->execute(['id'=>$interest]); db()->prepare('INSERT INTO matches (user_low_id,user_high_id,origin) VALUES (LEAST(:a,:b),GREATEST(:a,:b),:origin) ON CONFLICT (user_low_id,user_high_id) DO NOTHING')->execute(['a'=>$id,'b'=>$item['from_user_id'],'origin'=>$item['origin']]); flash('success','Match criado com consentimento recíproco.'); }
        elseif ($item && $decision === 'dismiss') { db()->prepare("UPDATE relationship_interests SET status='dismissed', responded_at=NOW() WHERE id=:id")->execute(['id'=>$interest]); flash('secondary','Oportunidade encerrada sem notificar uma rejeição explícita.'); }
        redirect('matches');
    }
    if ($intent === 'block') { $target=(int)$_POST['target_id']; db()->prepare('INSERT INTO blocks (blocker_id,blocked_id) VALUES (:a,:b) ON CONFLICT DO NOTHING')->execute(['a'=>$id,'b'=>$target]); db()->prepare("UPDATE matches SET status='blocked', ended_at=NOW() WHERE user_low_id=LEAST(:a,:b) AND user_high_id=GREATEST(:a,:b)")->execute(['a'=>$id,'b'=>$target]); db()->prepare("UPDATE relationship_interests SET status='invalidated' WHERE (from_user_id=:a AND to_user_id=:b) OR (from_user_id=:b AND to_user_id=:a)")->execute(['a'=>$id,'b'=>$target]); flash('success','Bloqueio aplicado; interesses e matches foram interrompidos.'); redirect('matches'); }
}

$page = $_GET['page'] ?? (current_user() ? 'dashboard' : 'login');
if ($page === 'login') { layout_start('Entrar', null); ?>
<div class="row justify-content-center pt-5"><div class="col-md-5"><div class="card shadow"><div class="card-body p-5"><h2 class="text-center text-primary"><i class="bi bi-heart-fill"></i> MyMatch</h2><p class="text-center text-muted">Conteúdo e relacionamentos, com escolhas independentes.</p><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="intent" value="login"><div class="mb-3"><label class="form-label">E-mail</label><input class="form-control" type="email" name="email" required></div><div class="mb-3"><label class="form-label">Senha</label><input class="form-control" type="password" name="password" required></div><button class="btn btn-primary w-100">Entrar</button></form><p class="small text-muted mt-4 mb-0">Use o usuário criado pelo script de dados de demonstração.</p></div></div></div></div><?php layout_end(); exit; }
$user=require_login(); $id=(int)$user['id'];
if ($page === 'dashboard') { $st=db()->prepare('SELECT c.*,p.display_name FROM content_posts c JOIN content_profiles p ON p.user_id=c.producer_id WHERE c.producer_id=:id ORDER BY c.created_at DESC LIMIT 5');$st->execute(['id'=>$id]);$posts=$st->fetchAll(); layout_start('Visão geral',$user); ?>
<div class="hero p-4 mb-4"><div class="row align-items-center"><div class="col"><h2>Você controla cada experiência.</h2><p class="mb-0">Conteúdo, relacionamentos e integração funcionam de modo independente.</p></div><div class="col-auto"><i class="bi bi-shield-heart display-4"></i></div></div></div><div class="row g-3"><div class="col-md-4"><div class="small-box text-bg-primary"><div class="inner"><h3><?= count($posts) ?></h3><p>Publicações recentes</p></div><i class="small-box-icon bi bi-collection-play"></i><a href="index.php?page=content" class="small-box-footer">Gerenciar <i class="bi bi-arrow-right"></i></a></div></div><div class="col-md-4"><div class="small-box text-bg-danger"><div class="inner"><h3>—</h3><p>Matches exigem reciprocidade</p></div><i class="small-box-icon bi bi-heart"></i><a href="index.php?page=discover" class="small-box-footer">Descobrir <i class="bi bi-arrow-right"></i></a></div></div><div class="col-md-4"><div class="small-box text-bg-success"><div class="inner"><h3>100%</h3><p>Controle de privacidade</p></div><i class="small-box-icon bi bi-shield-check"></i><a href="index.php?page=settings" class="small-box-footer">Revisar preferências <i class="bi bi-arrow-right"></i></a></div></div></div>
<div class="card"><div class="card-header"><h3 class="card-title">Princípio central</h3></div><div class="card-body">Consumir conteúdo não demonstra interesse; interesse unilateral não cria match; somente consentimento recíproco cria uma conexão.</div></div><?php layout_end(); exit; }
if ($page === 'settings') { $st=db()->prepare('SELECT * FROM user_settings WHERE user_id=:id');$st->execute(['id'=>$id]);$s=$st->fetch(); layout_start('Privacidade e perfis',$user); ?>
<form method="post" class="card"><div class="card-body"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="intent" value="settings"><h5>Participação</h5><?php foreach(['content_enabled'=>'Usar a área de conteúdo','dating_enabled'=>'Usar a área de relacionamentos','integration_enabled'=>'Permitir integração entre conteúdo e relacionamentos','visitor_identity_consent'=>'Autorizar uso de visitas válidas para descoberta'] as $field=>$label): ?><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" id="<?= $field ?>" name="<?= $field ?>" <?= !empty($s[$field])?'checked':'' ?>><label class="form-check-label" for="<?= $field ?>"><?= $label ?></label></div><?php endforeach; ?><div class="alert alert-info mb-0">Desativar a integração impede novas oportunidades originadas por acessos, sem alterar compras, assinaturas ou matches existentes.</div></div><div class="card-footer"><button class="btn btn-primary">Salvar preferências</button></div></form><?php layout_end(); exit; }
if ($page === 'content') { layout_start('Publicações',$user); ?>
<div class="card"><div class="card-header"><h3 class="card-title">Nova publicação</h3></div><form method="post"><div class="card-body row g-3"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="intent" value="publish"><div class="col-md-6"><label class="form-label">Título</label><input class="form-control" name="title" required></div><div class="col-md-3"><label class="form-label">Acesso</label><select class="form-select" name="access_type"><option value="free">Gratuito</option><option value="single_purchase">Compra avulsa</option><option value="subscription">Assinatura</option></select></div><div class="col-md-3"><label class="form-label">Visibilidade</label><select class="form-select" name="visibility"><option value="public">Público</option><option value="subscribers">Assinantes</option></select></div><div class="col-12"><label class="form-label">Descrição</label><textarea class="form-control" name="description"></textarea></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_adult" id="adult"><label class="form-check-label" for="adult">Conteúdo adulto (exige verificação de idade e consentimento)</label></div></div></div><div class="card-footer"><button class="btn btn-primary">Publicar</button></div></form></div><?php layout_end(); exit; }
if ($page === 'discover' || $page === 'visitors') { $visitor=$page==='visitors'; $sql=$visitor ? "SELECT DISTINCT rp.user_id, rp.display_name, rp.bio, rp.city FROM content_accesses a JOIN content_posts cp ON cp.id=a.content_id JOIN relationship_profiles rp ON rp.user_id=a.viewer_id JOIN user_settings s ON s.user_id=a.viewer_id WHERE cp.producer_id=:id AND a.is_valid AND s.integration_enabled AND s.visitor_identity_consent" : "SELECT rp.user_id,rp.display_name,rp.bio,rp.city FROM relationship_profiles rp JOIN user_settings s ON s.user_id=rp.user_id WHERE rp.user_id<>:id AND rp.is_active AND s.dating_enabled AND NOT EXISTS (SELECT 1 FROM blocks b WHERE (b.blocker_id=:id AND b.blocked_id=rp.user_id) OR (b.blocker_id=rp.user_id AND b.blocked_id=:id))"; $st=db()->prepare($sql);$st->execute(['id'=>$id]);$profiles=$st->fetchAll(); layout_start($visitor?'Visitantes elegíveis':'Descobrir pessoas',$user); ?>
<div class="alert alert-info"><i class="bi bi-info-circle"></i> <?= $visitor?'Somente visitas válidas, consentidas e elegíveis aparecem aqui.':'Perfis de relacionamento não dependem de consumo de conteúdo.' ?></div><div class="row g-3"><?php foreach($profiles as $p): ?><div class="col-md-4"><div class="card h-100"><div class="card-body"><h4><?= e($p['display_name']) ?></h4><p class="text-muted"><i class="bi bi-geo-alt"></i> <?= e($p['city'] ?: 'Localização não informada') ?></p><p><?= e($p['bio']) ?></p></div><div class="card-footer d-flex gap-2"><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="intent" value="like"><input type="hidden" name="target_id" value="<?= $p['user_id'] ?>"><input type="hidden" name="origin" value="<?= $visitor?'content_visit':'discovery' ?>"><input type="hidden" name="return_page" value="<?= $page ?>"><button class="btn btn-outline-danger"><i class="bi bi-heart"></i> Curtir</button></form></div></div></div><?php endforeach; if(!$profiles): ?><div class="col"><div class="card card-body text-muted">Nenhum perfil elegível agora.</div></div><?php endif; ?></div><?php layout_end(); exit; }
if ($page === 'matches') { $st=db()->prepare("SELECT i.*,rp.display_name FROM relationship_interests i JOIN relationship_profiles rp ON rp.user_id=i.from_user_id WHERE i.to_user_id=:id AND i.status='pending'");$st->execute(['id'=>$id]);$pending=$st->fetchAll(); $st=db()->prepare("SELECT m.*,rp.display_name, rp.user_id FROM matches m JOIN relationship_profiles rp ON rp.user_id=CASE WHEN m.user_low_id=:id THEN m.user_high_id ELSE m.user_low_id END WHERE (:id IN (m.user_low_id,m.user_high_id)) AND m.status='active'");$st->execute(['id'=>$id]);$matches=$st->fetchAll(); layout_start('Matches e oportunidades',$user); ?>
<div class="row g-3"><div class="col-lg-6"><div class="card"><div class="card-header"><h3 class="card-title">Oportunidades pendentes</h3></div><div class="list-group list-group-flush"><?php foreach($pending as $p): ?><div class="list-group-item"><strong><?=e($p['display_name'])?></strong> quer conhecer você.<div class="mt-2 d-flex gap-2"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="respond"><input type="hidden" name="interest_id" value="<?= $p['id'] ?>"><input type="hidden" name="decision" value="like"><button class="btn btn-sm btn-danger">Curtir de volta</button></form><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="respond"><input type="hidden" name="interest_id" value="<?= $p['id'] ?>"><input type="hidden" name="decision" value="dismiss"><button class="btn btn-sm btn-outline-secondary">Agora não</button></form></div></div><?php endforeach; if(!$pending): ?><div class="list-group-item text-muted">Sem oportunidades pendentes.</div><?php endif;?></div></div></div><div class="col-lg-6"><div class="card"><div class="card-header"><h3 class="card-title">Seus matches</h3></div><div class="list-group list-group-flush"><?php foreach($matches as $m): ?><div class="list-group-item d-flex justify-content-between align-items-center"><span><span class="match-dot me-2"></span><?=e($m['display_name'])?></span><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="block"><input type="hidden" name="target_id" value="<?= $m['user_id'] ?>"><button class="btn btn-sm btn-outline-danger">Bloquear</button></form></div><?php endforeach; if(!$matches): ?><div class="list-group-item text-muted">Ainda não há matches.</div><?php endif;?></div></div></div></div><?php layout_end(); exit; }
http_response_code(404); layout_start('Página não encontrada',$user); echo '<div class="alert alert-warning">Página não encontrada.</div>'; layout_end();
